  select u.Id user_id,
         u.DisplayName displayname,
         cluster_users.rank_pos rank_within_cluster
  from Users u
  join (
     select UserId, 
            row_number() over(partition by cnt_cluster order by Reputation desc) as rank_pos
     from (
       select u.Id as UserId,u.Reputation,
         dense_rank() over (order by FameCluster desc) as cnt_cluster
       from (select Id,Reputation,
                    ntile(10) over (order by Reputation desc) rid,
                    ntile(300) over (order by Reputation desc) FameCluster
             from Users
             where Id is not null
